ALTER TABLE "dictionary_generation_jobs" ADD CONSTRAINT "dictionary_generation_jobs_ai_credit_state" CHECK ((coalesce("dictionary_generation_jobs"."selected_execution_snapshot"->>'actionAccountingVersion', '') = '1' and "dictionary_generation_jobs"."ai_credit_accounted" = false and "dictionary_generation_jobs"."ai_credit_reservation_id" is null) or ("dictionary_generation_jobs"."ai_credit_accounted" = false and "dictionary_generation_jobs"."ai_credit_input_credits_per_million_tokens" is null and "dictionary_generation_jobs"."ai_credit_max_credits_per_attempt" is null and "dictionary_generation_jobs"."ai_credit_output_credits_per_million_tokens" is null and "dictionary_generation_jobs"."ai_credit_policy_mode" is null and "dictionary_generation_jobs"."ai_credit_pricing_revision" is null and "dictionary_generation_jobs"."ai_credit_provider_dispatched_at" is null and "dictionary_generation_jobs"."ai_credit_reservation_id" is null) or ("dictionary_generation_jobs"."ai_credit_accounted" = true and "dictionary_generation_jobs"."ai_credit_input_credits_per_million_tokens" >= 0 and "dictionary_generation_jobs"."ai_credit_max_credits_per_attempt" > 0 and "dictionary_generation_jobs"."ai_credit_output_credits_per_million_tokens" >= 0 and "dictionary_generation_jobs"."ai_credit_pricing_revision" = 1 and ("dictionary_generation_jobs"."ai_credit_policy_mode" is null or "dictionary_generation_jobs"."ai_credit_policy_mode" in ('limited', 'unlimited')) and ("dictionary_generation_jobs"."ai_credit_provider_dispatched_at" is null or "dictionary_generation_jobs"."ai_credit_policy_mode" is not null)));--> statement-breakpoint
ALTER TABLE "ai_credit_action_attempts" ADD CONSTRAINT "ai_credit_action_attempt_meter" CHECK (("ai_credit_action_attempts"."input_tokens" is null and "ai_credit_action_attempts"."output_tokens" is null) or ("ai_credit_action_attempts"."input_tokens" is not null and "ai_credit_action_attempts"."output_tokens" is not null and "ai_credit_action_attempts"."input_tokens" between 0 and "ai_credit_action_attempts"."input_limit" and "ai_credit_action_attempts"."output_tokens" between 0 and "ai_credit_action_attempts"."output_limit"));--> statement-breakpoint
ALTER TABLE "ai_credit_actions" ADD CONSTRAINT "ai_credit_action_terminal" CHECK (("ai_credit_actions"."state"='active' and "ai_credit_actions"."settled_at" is null and "ai_credit_actions"."charged_milli" is null and "ai_credit_actions"."outcome" is null and "ai_credit_actions"."measurement" is null) or ("ai_credit_actions"."state"='settled' and "ai_credit_actions"."settled_at" is not null and "ai_credit_actions"."outcome" is not null and "ai_credit_actions"."charged_milli" is not null and "ai_credit_actions"."measurement" is not null and "ai_credit_actions"."outcome" in ('success','stopped','failure') and "ai_credit_actions"."measurement" in ('measured','unknown') and "ai_credit_actions"."charged_milli" between 0 and "ai_credit_actions"."held_milli" and ("ai_credit_actions"."outcome"<>'failure' or "ai_credit_actions"."charged_milli"=0)));--> statement-breakpoint
ALTER TABLE "ai_operator_action_budgets" ADD CONSTRAINT "ai_operator_action_terminal" CHECK (("ai_operator_action_budgets"."state"='active' and "ai_operator_action_budgets"."consumed_micros" is null and "ai_operator_action_budgets"."settled_at" is null) or ("ai_operator_action_budgets"."state"='settled' and "ai_operator_action_budgets"."consumed_micros" is not null and "ai_operator_action_budgets"."consumed_micros" between 0 and "ai_operator_action_budgets"."reserved_micros" and "ai_operator_action_budgets"."settled_at" is not null));--> statement-breakpoint
ALTER TABLE "ai_operator_attempt_costs" ADD CONSTRAINT "ai_operator_attempt_terminal" CHECK (("ai_operator_attempt_costs"."settled_at" is null and "ai_operator_attempt_costs"."consumed_micros" is null and "ai_operator_attempt_costs"."measurement" is null) or ("ai_operator_attempt_costs"."settled_at" is not null and "ai_operator_attempt_costs"."consumed_micros" is not null and "ai_operator_attempt_costs"."measurement" is not null and "ai_operator_attempt_costs"."consumed_micros" between 0 and "ai_operator_attempt_costs"."reserved_micros" and "ai_operator_attempt_costs"."measurement" in ('measured','conservative')));